SELECT COALESCE(SUM(num) / 6340.0, 0)
FROM tb_grid_permanent_num
WHERE population_type = 'HOME'
  AND city_code = #{cityCode}
  AND date = #{date}

SELECT COALESCE(SUM(num) / 6340.0, 0)
FROM tb_grid_permanent_num
WHERE population_type = 'WORK'
  AND city_code = #{cityCode}
  AND date = #{date}

SELECT city_code
FROM tb_grid
WHERE grid_id = #{gridId}

SELECT COALESCE(COUNT(1) * 14400.0, 0)
FROM tb_grid
WHERE city_code = #{cityCode}
